from pathlib import Path
import csv,json,statistics,html,shutil
from collections import defaultdict
ROOT=Path(__file__).resolve().parents[3]
IDS=['Hinds_etal_2008','Cerkevich_Qi_Kaas_2014','Barton_etal_2012','SanchezPanchuelo_etal_2018','Willoughby_etal_2021'];out=ROOT/'flatmap_measurements/recommended_2026-10-31';out.mkdir(exist_ok=True)
def writecsv(p,rs,fields=None):
 with p.open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=fields or list(rs[0]));w.writeheader();w.writerows(rs)
merged=[];summaries=[];comparisons=[];sections=[]
for ident in IDS:
 p=ROOT/'flatmap_measurements'/ident;rows=list(csv.DictReader((p/'data/measurements.csv').open()));groups=defaultdict(list);sens=[];details=[]
 for r in rows:
  rr=dict(paper_id=ident,**r);merged.append(rr)
  if r['area_px2']=='NA':continue
  d=json.loads((p/'figures'/r['map_id']/'rois.json').read_text());repeat=bool(d.get('repeat_of'));unit='mm2' if r['area_mm2']!='NA' else 'display_px2';val=float(r['area_mm2'] if unit=='mm2' else r['area_px2'])
  if not repeat:groups[(r['species'],r['label'],unit)].append(val)
  if unit=='mm2':
   length=float(r['scale_length_px']);sens.append(dict(map_id=r['map_id'],label=r['label'],area_mm2=val,bar_length_px=length,area_if_bar_2px_longer_mm2=val*(length/(length+2))**2,area_if_bar_2px_shorter_mm2=val*(length/(length-2))**2,interpretation='Each endpoint moved outward/inward by 1 rendered pixel; scale-only sensitivity, not a confidence interval'))
  native=d.get('native_area_mm2')
  if native:
   comparisons.append(dict(map_id=r['map_id'],specimen=r['specimen'],hemisphere=r['hemisphere'],trace_2d_mm2=val,published_native_mm2=native,difference_percent=100*(val/native-1),source='Hinds Table 2',interpretation='Separate 2D tracing and native-surface quantities; no forced rescaling'))
  details.append('<tr><td>'+html.escape(r['map_id'])+('</td><td>repeat check' if repeat else '</td><td>target')+'</td><td>'+html.escape(r['label'])+'</td><td>'+f'{val:.2f} {unit}'+'</td><td><a href="../'+ident+'/figures/'+r['map_id']+'/source.tif">ImageJ TIFF</a> · <a href="../'+ident+'/figures/'+r['map_id']+'/RoiSet.zip">ROIs</a> · <a href="../'+ident+'/figures/'+r['map_id']+'/tracing.png">overlay</a></td></tr>')
 stats=[]
 for (species,label,unit),values in groups.items():
  stats.append(dict(paper_id=ident,species=species,label=label,unit=unit,n_nonrepeated_views=len(values),mean=statistics.mean(values),sample_sd=statistics.stdev(values) if len(values)>1 else 'NA',minimum=min(values),maximum=max(values),interpretation='Descriptive field-view statistics only; hemispheres may be paired. Display-pixel means are not biological areas. No whole-cortex denominator.'))
 writecsv(p/'data/field_observation_summary.csv',stats);summaries+=stats
 if sens:writecsv(p/'documentation/scale_sensitivity.csv',sens)
 validation=json.loads((p/'documentation/validation.json').read_text());review=dict(date='2026-10-31',scope='Brecht-target fields in supplied main-text PDFs',source_and_overlay_views_inspected=[x.parent.name for x in (p/'figures').glob('*/rois.json')],anatomical_status='provisional_pending_domain_review',inventory_complete_for_scope=True,whole_neocortex_denominator_available=False,native_imagej_roundtrip=validation['native_imagej_roundtrip'],notes='Every target overlay inspected; missing and out-of-scope regions documented. Native checks are file/geometry checks, not anatomical certification.')
 (p/'documentation/review_record.json').write_text(json.dumps(review,indent=2)+'\n')
 sections.append('<section><h2>'+ident+'</h2><p><a href="../'+ident+'/review/gallery.html">Source ↔ tracing gallery</a> · <a href="../'+ident+'/data/measurements.csv">Measurements CSV</a> · <a href="../'+ident+'/documentation/figure_inventory.csv">Figure inventory</a> · <a href="../'+ident+'/documentation/methods.md">Methods</a></p><table><tr><th>View</th><th>Use</th><th>Region</th><th>Traced area</th><th>Editable files</th></tr>'+''.join(details)+'</table></section>')
writecsv(out/'measurements_all_papers.csv',merged);writecsv(out/'field_observation_summary.csv',summaries)
p=ROOT/'flatmap_measurements/Hinds_etal_2008/comparison';p.mkdir(exist_ok=True);writecsv(p/'tracing_vs_published_table2.csv',comparisons)
hindmean=statistics.mean(x['trace_2d_mm2'] for x in comparisons);native_mean=statistics.mean(x['published_native_mm2'] for x in comparisons);diff=100*(hindmean/native_mean-1)
barton={r['map_id']:float(r['area_mm2']) for r in merged if r['paper_id']=='Barton_etal_2012' and r['area_mm2']!='NA'};bdiff=100*(barton['fig03_S4_R_repeat_check']/barton['fig02_S4_R']-1)
writecsv(ROOT/'flatmap_measurements/Barton_etal_2012/documentation/repeated_figure_check.csv',[dict(specimen='S4',hemisphere='right',fig2_mm2=barton['fig02_S4_R'],fig3_mm2=barton['fig03_S4_R_repeat_check'],difference_percent=bdiff,interpretation='Same tissue, independent figure bars; excluded repeat from observation summary. Difference retained, not rescaled.')])
# Update scope wording to account for the intentional QC duplicate.
p=ROOT/'flatmap_measurements/Barton_etal_2012'
for f in [p/'README.md',p/'documentation/methods.md']:
 s=f.read_text();s=s.replace('Fig.3 S4 right repeats Fig.2 and is excluded from independent summaries.','Fig.3 S4 right is additionally traced as a scale/geometry check and excluded from independent summaries.');f.write_text(s)
page='''<!doctype html><html><head><meta charset="utf-8"><title>Brecht alternatives — tracing review</title><style>body{font:16px/1.5 system-ui;max-width:1350px;margin:36px auto;padding:0 24px;color:#1c2c39}table{border-collapse:collapse;width:100%;margin:18px 0}th,td{padding:9px;border:1px solid #cbd5df;text-align:left;vertical-align:top}th{background:#eaf1f6}a{color:#145e96}section{margin-top:38px}.notice{background:#fff5dd;padding:18px;border-left:4px solid #b88425}small{color:#506070}</style></head><body><h1>Brecht alternatives: tracing review</h1><p>31 October 2026 · Five supplied papers · <b>19 calibrated target-field tracings, 7 pixel-only response footprints, and 1 repeated-figure check.</b> One additional forehead view (Willoughby D) is explicitly unmeasurable from the print; its published cluster area is preserved.</p><div class="notice"><b>Use restrictions.</b> Macaque face measurements are <b>3b face + oral</b>, not Brecht’s putative 3a+3b or external face alone. Human cheek/forehead footprints cannot replace complete S1-face. Calibrated figure areas are 2D estimates; native mesh areas are separate. All anatomical traces remain provisional. No whole-cortex percentages or artificial cortex totals were calculated.</div><p><a href="measurements_all_papers.csv">All measurement rows</a> · <a href="field_observation_summary.csv">Descriptive field-view summary</a></p><h2>Checks and comparisons</h2><ul><li>Native ImageJ read-back passed for every exported selection: calibration, image pixels, ROI masks and mask stacks. Area equations, missing values, unique keys and file hashes passed. Every processed source/overlay was inspected.</li><li>Hinds: mean traced V1 '''+f'{hindmean:.1f}'+''' mm² versus mean of the tabulated native values '''+f'{native_mean:.1f}'+''' mm² ('''+f'{diff:.1f}%'+'''). The paper reports its rounded mean as 2960 mm². The systematic difference is unresolved; no scale was fitted to the benchmark. <a href="../Hinds_etal_2008/comparison/tracing_vs_published_table2.csv">Case comparison</a>.</li><li>Barton S4 right: Figure 2 '''+f'{barton["fig02_S4_R"]:.1f}'+''' versus Figure 3 '''+f'{barton["fig03_S4_R_repeat_check"]:.1f}'+''' mm² ('''+f'{bdiff:.1f}%'+'''). Same tissue; count once. Short printed bars make endpoint placement material; scale-only sensitivity scenarios are saved per calibrated paper.</li><li>Willoughby: <a href="../Willoughby_etal_2021/comparison/published_forehead_clusters.csv">Table 1 forehead cluster areas</a> and <a href="../Willoughby_etal_2021/comparison/published_forehead_subject_sums.csv">derived per-subject sums</a> are kept separate from traced display pixels.</li><li>Barton supplementary maps and Figure S6 were not supplied. Three of eight hemispheres and the published numerical area check remain unavailable. Non-target auditory fields, digit maps and SII maps are inventoried separately.</li></ul>'''+''.join(sections)+'''<p><small>Open a source.tif in ImageJ/Fiji for the calibrated image and overlay, or import its RoiSet.zip. These contain the same selections. Canonical editable vertices and provenance are in each rois.json. Preserve edits before rebuilding.</small></p></body></html>'''
(out/'index.html').write_text(page)
print('Report:',out/'index.html');print('Hinds mean',hindmean,'native',native_mean,'difference',diff);print('Rows',len(merged));print('Nonrepeated measured',sum(int(s['n_nonrepeated_views']) for s in summaries))
